const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;

const ambientLight = new THREE.AmbientLight(0xdde6ff, 1.2);
scene.add(ambientLight);

const floor = new THREE.Mesh(
  new THREE.CircleGeometry(10, 96),
  new THREE.MeshStandardMaterial({ color: 0xe6ecf5, roughness: 0.92, metalness: 0.02 })
);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -1.2;
scene.add(floor);

const heroGroup = new THREE.Group();
scene.add(heroGroup);

const geometry = new THREE.BoxGeometry(1.8, 1.8, 1.8, 4, 4, 4);
const material = new THREE.MeshPhysicalMaterial({
  color: 0x2563eb,
  metalness: 0.15,
  roughness: 0.25,
  clearcoat: 0.8,
  clearcoatRoughness: 0.15,
  reflectivity: 0.9,
  ior: 1.47,
  sheen: 0.3,
  sheenColor: 0x4f8dff
});
const cube = new THREE.Mesh(geometry, material);
cube.castShadow = true;
cube.receiveShadow = true;
cube.position.y = 0.6;
heroGroup.add(cube);

camera.position.set(4.4, 2.4, 5.2);
camera.lookAt(0, 0.6, 0);

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  heroGroup.rotation.y = t * 0.35;
  heroGroup.rotation.x = Math.sin(t * 0.25) * 0.08;
  cube.position.y = 0.6 + Math.sin(t * 1.8) * 0.06;

  renderer.render(scene, camera);
}
animate();

